'use strict';
const SEGMENT_COLORS={'Time & date':'#b7becd','Chronograph':'#89b6cf','Diving':'#60a99d','Travel & GMT':'#b3a3d4','Complications':'#d7b775','Jewellery':'#d797a9'};
const MOVEMENT_COLORS={'Automatic':'#d7b775','Manual':'#9b9ac4','Quartz':'#7fafbc','Not specified':'#4a4c57'};
function summarizeWatches(rows,name){
const ds=rows.filter(r=>r.diameter_mm!==null).map(r=>r.diameter_mm),g=rows.filter(r=>r.gem_set).length;
const counts=key=>rows.reduce((a,r)=>(a[r[key]]=(a[r[key]]||0)+1,a),{});
return{name,count:rows.length,diameterN:ds.length,diameterAvg:ds.length?ds.reduce((a,b)=>a+b,0)/ds.length:null,diameterMin:ds.length?Math.min(...ds):null,diameterMax:ds.length?Math.max(...ds):null,gemCount:g,gemPercent:rows.length?g/rows.length*100:0,calibers:new Set(rows.filter(r=>r.caliber_key).map(r=>r.brand+'|'+r.caliber_key)).size,caliberN:rows.filter(r=>r.caliber_key).length,movements:counts('movement_family'),segments:counts('segment'),collections:counts('collection_label'),stones:rows.reduce((a,r)=>(r.gemstones.forEach(stone=>a[stone]=(a[stone]||0)+1),a),{})};
}
function insightRows(){return DATA.records.filter(r=>r.is_watch&&(state.insightBrand==='All watchmakers'||r.brand===state.insightBrand));}
function insightSummary(){
const rows=insightRows();return{overall:summarizeWatches(rows,state.insightBrand),segments:DATA.insights.categories.map(c=>summarizeWatches(rows.filter(r=>r.segment===c),c)).filter(c=>c.count),brands:DATA.brands.filter(b=>b.records).map(b=>summarizeWatches(rows.filter(r=>r.brand===b.name),b.name)).filter(b=>b.count)};
}
function insightHeader(number,title,description){return `<div class="chart-title"><span class="section-index">${number}</span><div><h2>${title}</h2><p>${description}</p></div></div>`;}
function segmentLegend(){return `<div class="chart-legend">${Object.entries(SEGMENT_COLORS).map(([n,c])=>`<span><i style="background:${c}"></i>${n}</span>`).join('')}</div>`;}
function movementStack(x){return `<div class="stacked-bar" aria-label="${esc(Object.entries(x.movements).map(([m,n])=>`${m}: ${n} watches`).join(', '))}">${Object.entries(MOVEMENT_COLORS).map(([m,c])=>x.movements[m]?`<span title="${m}: ${x.movements[m]}" style="width:${x.movements[m]/x.count*100}%;background:${c}"></span>`:'').join('')}</div>`;}
function insights(){const a=insightSummary();const s=a.overall;const biggest=a.segments.filter(x=>x.diameterAvg!==null).sort((a,b)=>b.diameterAvg-a.diameterAvg)[0];const gemLeader=[...a.brands].sort((a,b)=>b.gemPercent-a.gemPercent)[0];const mostCalibers=[...a.segments].sort((a,b)=>b.calibers-a.calibers)[0];
return `${viewIntro('PATTERNS IN THE COLLECTION','The details tell a bigger story.','Compare watchmakers, explore their catalog mix, and see how size, stones and mechanics vary across the collection.')}<div class="insight-toolbar"><span>Explore the collection</span><select id="insight-brand" aria-label="Watchmaker for insights">${['All watchmakers',...DATA.insights.brands.map(b=>b.name)].map(b=>`<option ${b===state.insightBrand?'selected':''}>${esc(b)}</option>`).join('')}</select><span class="scope-count">${fmt(s.count)} watches · 2023–2024 snapshot</span></div>
<div class="insight-takeaways"><article><span class="tiny-label">LARGEST AVERAGE CASE</span><h3>${esc(biggest?.name||'Not available')}</h3><strong>${biggest?biggest.diameterAvg.toFixed(1)+' <small>mm</small>':'—'}</strong><p>Based on ${fmt(biggest?.diameterN||0)} measured watches.</p></article><article><span class="tiny-label">HIGHEST GEMSTONE SHARE</span><h3>${esc(gemLeader.name)}</h3><strong>${gemLeader.gemPercent.toFixed(1)}<small>%</small></strong><p>${fmt(gemLeader.gemCount)} of ${fmt(gemLeader.count)} watches mention decorative stones.</p></article><article><span class="tiny-label">WIDEST CALIBER VARIETY</span><h3>${esc(mostCalibers.name)}</h3><strong>${mostCalibers.calibers}<small> calibers</small></strong><p>Recorded in ${fmt(mostCalibers.caliberN)} watches with caliber information.</p></article></div>
<section class="panel brand-panel">${insightHeader('01','What each watchmaker brings.','Catalog mix by primary segment. Select a segment to explore the watches behind it.')}<div class="brand-fingerprints">${a.brands.map(b=>`<article class="brand-fingerprint"><div class="brand-head"><h3>${esc(b.name)}</h3><span>${fmt(b.count)} watches</span></div><div class="stacked-bar segment-stack" aria-label="${esc(Object.entries(b.segments).map(([c,n])=>c+': '+n).join(', '))}">${DATA.insights.categories.map(c=>b.segments[c]?`<button data-explore-segment="${esc(c)}" data-explore-brand="${esc(b.name)}" aria-label="Explore ${esc(b.name+' '+c)}: ${b.segments[c]} watches" title="${esc(c)}: ${b.segments[c]}" style="width:${b.segments[c]/b.count*100}%;background:${SEGMENT_COLORS[c]}"></button>`:'').join('')}</div><div class="brand-segments">${Object.entries(b.segments).sort((a,b)=>b[1]-a[1]).map(([c,n])=>`<button data-explore-segment="${esc(c)}" data-explore-brand="${esc(b.name)}"><i style="background:${SEGMENT_COLORS[c]}"></i>${esc(c)} <b>${n}</b></button>`).join('')}</div><details class="collection-disclosure"><summary>${Object.keys(b.collections).length} collections</summary><div class="collection-tags">${Object.entries(b.collections).sort((a,b)=>b[1]-a[1]).map(([c,n])=>`<button data-explore-collection="${esc(c)}" data-explore-brand="${esc(b.name)}">${esc(c)} <small>${n}</small></button>`).join('')}</div></details></article>`).join('')}</div>${segmentLegend()}</section>
<div class="insight-charts"><section class="panel">${insightHeader('02','Which watches wear larger?','Average diameter by segment. Round case measurements only.')}<div class="diameter-chart">${[...a.segments].filter(x=>x.diameterAvg!==null).sort((a,b)=>b.diameterAvg-a.diameterAvg).map(x=>`<button class="diameter-row" data-explore-segment="${esc(x.name)}" data-explore-brand="${esc(state.insightBrand)}"><div class="chart-row-label"><span>${esc(x.name)}</span><strong>${x.diameterAvg.toFixed(1)} <small>mm</small></strong></div><div class="chart-track"><span style="width:${x.diameterAvg/60*100}%;background:${SEGMENT_COLORS[x.name]}"></span></div><div class="chart-row-note">${fmt(x.diameterN)} measured · ${x.diameterMin.toFixed(1)}–${x.diameterMax.toFixed(1)} mm range</div></button>`).join('')}<div class="chart-axis"><span>0</span><span>30</span><span>60 mm</span></div></div><p class="chart-foot">${fmt(s.diameterN)} of ${fmt(s.count)} watches have a usable diameter. Non-round dimensions and missing values are excluded.</p></section>
<section class="panel">${insightHeader('03','A taste for precious stones.','Share of watches with explicit decorative gemstone mentions.')}<div class="gem-chart">${[...a.brands].sort((a,b)=>b.gemPercent-a.gemPercent).map(b=>`<button class="gem-row" data-explore-gems="true" data-explore-brand="${esc(b.name)}"><div class="chart-row-label"><span>${esc(b.name)}</span><strong>${b.gemPercent.toFixed(1)}<small>%</small></strong></div><div class="chart-track"><span style="width:${b.gemPercent}%;background:linear-gradient(90deg,#937048,#e2c796)"></span></div><div class="chart-row-note">${fmt(b.gemCount)} / ${fmt(b.count)} watches · ${Object.keys(b.stones).length} identified stone types</div><div class="stone-note">${Object.entries(b.stones).sort((a,b)=>b[1]-a[1]).slice(0,3).map(([stone,n])=>esc(stone)+' · '+fmt(n)).join(' &nbsp; / &nbsp; ')}</div></button>`).join('')}</div><p class="chart-foot">Diamonds and gem settings count. Sapphire crystals and movement-bearing jewels do not. No mention means unconfirmed, rather than stone-free.</p></section></div>
<section class="panel movement-panel">${insightHeader('04','What makes them tick?','Movement families and caliber variety answer two different questions.')}<div class="movement-layout"><div><h3>Movement mix by watchmaker</h3>${a.brands.map(b=>`<div class="movement-row"><div class="chart-row-label"><span>${esc(b.name)}</span><small>${fmt(b.count)} watches</small></div>${movementStack(b)}<div class="movement-counts">${Object.entries(b.movements).map(([m,n])=>`<span>${m} <b>${n}</b></span>`).join('')}</div></div>`).join('')}<div class="chart-legend">${Object.entries(MOVEMENT_COLORS).map(([m,c])=>`<span><i style="background:${c}"></i>${m}</span>`).join('')}</div></div><div><h3>Caliber variety by segment</h3><div class="caliber-list">${[...a.segments].sort((a,b)=>b.calibers-a.calibers).map(c=>`<button data-explore-segment="${esc(c.name)}" data-explore-brand="${esc(state.insightBrand)}"><span style="color:${SEGMENT_COLORS[c.name]}">${esc(c.name)}</span><strong>${c.calibers}</strong><small>distinct calibers · ${fmt(c.caliberN)} / ${fmt(c.count)} watches identified</small></button>`).join('')}</div><p class="chart-foot">A caliber is a named movement design. These counts describe variety; they do not imply several movements inside one watch. Calibers are counted separately by watchmaker.</p></div></div><details class="segment-movements"><summary>Compare movement families by watch segment</summary><div class="segment-movement-grid">${a.segments.map(c=>`<article><div class="chart-row-label"><span>${esc(c.name)}</span><small>${fmt(c.count)} watches</small></div>${movementStack(c)}<div class="movement-counts">${Object.entries(c.movements).map(([m,n])=>`<span>${m} <b>${n}</b></span>`).join('')}</div></article>`).join('')}</div></details></section>
<details class="analysis-notes"><summary>How to read these comparisons</summary><div><p>This is a comparison within the collected 2023–2024 snapshot. Catalog sizes and documentation differ between watchmakers, so the results do not represent their entire current ranges.</p><p>Each watch has one inferred primary segment. Complications take precedence over chronographs, diving, travel and jewellery families; remaining models fall under time & date. Classification uses the captured model names and stated functions. Gem details are a separate attribute, so a time & date watch can also be diamond-set.</p><p>Case size uses a single diameter value, or an explicit diameter in the captured description when the field is missing. Rectangular dimensions are excluded. One wall clock is retained in the project data but excluded from wristwatch insights and the watch catalog.</p><p>Gemstones are identified from decorative materials, dials, bezels, bracelets and descriptions. Movement families are read from the movement field or explicit wording in descriptions. Missing information remains unspecified. Some archived descriptions differ from their model labels; the comparisons reflect those stored descriptions, without independent verification.</p><p>Caliber names are normalized for spacing and descriptive suffixes. Missing calibers reduce the observable variety, especially in the jewellery segment.</p></div></details>`;
}
